255	    {
256	        if (auto * query_node = updated_query_tree->as<QueryNode>())
257	        {
258	            auto new_context = Context::createCopy(query_node->getMutableContext());
259	            new_context->setSetting("enable_parallel_replicas", false);
260	            query_node->getMutableContext() = new_context;
261	        }
262	        else if (auto * union_node = updated_query_tree->as<UnionNode>())
263	        {
264	            auto new_context = Context::createCopy(union_node->getMutableContext());
