270	    std::unordered_map<const IStorage *, QueryTreeNodePtr> dummy_storage_to_table;
271	
272	    for (auto & [from_table_expression, dummy_table_expression] : replacement_map)
273	    {
274	        auto * dummy_storage = dummy_table_expression->as<TableNode &>().getStorage().get();
275	        dummy_storage_to_table.emplace(dummy_storage, from_table_expression);
276	    }
277	
278	    SelectQueryOptions select_query_options;
279	    Planner planner(updated_query_tree, select_query_options);
280	    planner.buildQueryPlanIfNeeded();
281	
282	    auto & result_query_plan = planner.getQueryPlan();
283	
284	    /// This part is needed to support "skip unused shards" for the View over Distributed.
285	    /// When reading through a View, the outer WHERE clause is not visible to the inner query.
286	    /// Inject it as a FilterStep on top of the dummy plan so that predicate-push-down works.
287	    if (post_filter)
288	    {
289	        const auto & header = *result_query_plan.getCurrentHeader();
290	        bool all_inputs_present = true;
291	        for (const auto & input : post_filter->getInputs())
292	        {
293	            if (!header.has(input->result_name))
