310	            result_query_plan.addStep(std::move(filter_step));
311	        }
312	    }
313	
314	    QueryPlanOptimizationSettings optimization_settings(query_context);
315	    optimization_settings.build_sets = false; // no need to build sets to collect filters
316	    optimization_settings.materialize_ctes = false; // no need to materialize CTEs to collect filters
317	    result_query_plan.optimize(optimization_settings);
318	
319	    FiltersForTableExpressionMap res;
320	
321	    std::vector<QueryPlan::Node *> nodes_to_process;
322	    nodes_to_process.push_back(result_query_plan.getRootNode());
323	
324	    while (!nodes_to_process.empty())
325	    {
326	        const auto * node_to_process = nodes_to_process.back();
327	        nodes_to_process.pop_back();
328	        nodes_to_process.insert(nodes_to_process.end(), node_to_process->children.begin(), node_to_process->children.end());
