336	            const auto & table_node = dummy_storage_to_table.at(&read_from_dummy->getStorage());
337	            res[table_node] = FiltersForTableExpression{filter_actions, read_from_dummy->getPrewhereInfo()};
338	        }
339	    }
340	
341	    return res;
